import React, { useState, useEffect } from 'react';
import { getAssociatedFranchises } from '../services/api';

const ExamDataUser = () => {
  const [examDataList, setExamDataList] = useState([]);

  useEffect(() => {
    const fetchExamData = async () => {
      try {
        const franchises = await getAssociatedFranchises();
        if (franchises.length > 0) {
          setExamDataList(franchises[0].examData || []);
        } else {
          setExamDataList([]);
        }
      } catch (error) {
        console.error('Error fetching exam data:', error);
        alert('Unable to retrieve exam data. Please try again later.');
      }
    };

    fetchExamData();
  }, []);

  return (
    <div>
      <h1>Exam Data</h1>

      {/* Table to display exam data */}
      {examDataList.length > 0 ? (
        <table border="1">
          <thead>
            <tr>
              <th>Exam Name</th>
              <th>Date</th>
              <th>Students Attended</th>
            </tr>
          </thead>
          <tbody>
            {examDataList.map((exam, index) => (
              <tr key={index}>
                <td>{exam.examName}</td>
                <td>{exam.date}</td>
                <td>{exam.studentsAttended}</td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <p>No exam data available for your franchise.</p>
      )}
    </div>
  );
};

export default ExamDataUser;
